:root {
  --bg: #1e1a2e;
  --card: #2d2640;
  --text: #f0e6d2;
  --accent: #e8a87c;
  --accent-dark: #c47f5a;
  --muted: #8a7f9e;
  --green: #6fcf97;
  --shadow: #0f0c18;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: 
    linear-gradient(45deg, #2a2340 25%, transparent 25%),
    linear-gradient(-45deg, #2a2340 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #2a2340 75%),
    linear-gradient(-45deg, transparent 75%, #2a2340 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
  font-family: 'Courier New', Courier, monospace;
  color: var(--text);
  padding: 20px;
}

.card {
  background: var(--card);
  border: 4px solid var(--shadow);
  border-radius: 0;
  padding: 30px 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 8px 8px 0 var(--shadow);
  text-align: center;
}

h1 {
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--shadow);
}

.mode-indicator {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
}

.mode-btn {
  font-family: inherit;
  font-size: 16px;
  padding: 10px 20px;
  background: var(--bg);
  color: var(--muted);
  border: 3px solid var(--shadow);
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, color 0.1s, transform 0.1s;
}

.mode-btn:hover {
  background: #3a3152;
  color: var(--text);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translate(2px, 2px);
}

.mode-btn.active {
  background: var(--accent);
  color: var(--shadow);
  border-color: var(--accent-dark);
}

.mode-btn.active:hover {
  background: var(--accent-dark);
}

.timer {
  font-size: 64px;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 20px 0 30px;
  color: var(--text);
  text-shadow: 4px 4px 0 var(--shadow);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.btn {
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  padding: 14px 28px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--shadow);
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 var(--shadow);
}

.btn:hover {
  background: #3a3152;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.btn.primary {
  background: var(--accent);
  color: var(--shadow);
  border-color: var(--accent-dark);
}

.btn.primary:hover {
  background: var(--accent-dark);
}

.btn.primary:focus-visible {
  outline-color: var(--text);
}

.hint {
  font-size: 14px;
  color: var(--muted);
  line-height: 1.5;
}

@media (max-width: 420px) {
  .timer {
    font-size: 48px;
    letter-spacing: 2px;
  }
  .card {
    padding: 24px 16px;
  }
  .btn {
    padding: 12px 20px;
    font-size: 16px;
  }
  h1 {
    font-size: 20px;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

const timerDisplay = document.getElementById('timerDisplay');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workModeBtn = document.getElementById('workMode');
const breakModeBtn = document.getElementById('breakMode');

let currentMode = 'work';
let timeLeft = WORK_TIME;
let timerId = null;
let isRunning = false;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(timeLeft);
}

function setMode(mode) {
  if (isRunning) return;
  currentMode = mode;
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
  workModeBtn.classList.toggle('active', mode === 'work');
  workModeBtn.setAttribute('aria-pressed', mode === 'work');
  breakModeBtn.classList.toggle('active', mode === 'break');
  breakModeBtn.setAttribute('aria-pressed', mode === 'break');
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
  timerId = setInterval(() => {
    timeLeft--;
    updateDisplay();
    if (timeLeft <= 0) {
      clearInterval(timerId);
      timerId = null;
      isRunning = false;
      startPauseBtn.textContent = 'Start';
      startPauseBtn.setAttribute('aria-label', 'Start timer');
      // Auto-switch mode on completion
      if (currentMode === 'work') {
        setMode('break');
      } else {
        setMode('work');
      }
    }
  }, 1000);
}

function pauseTimer() {
  if (!isRunning) return;
  clearInterval(timerId);
  timerId = null;
  isRunning = false;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function resetTimer() {
  pauseTimer();
  timeLeft = currentMode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

startPauseBtn.addEventListener('click', () => {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);

workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

// Initialize
updateDisplay();
